package com.myeshopping.invoiceservice.service;
import com.myeshopping.invoiceservice.dto.InvoiceRequest; import com.myeshopping.invoiceservice.entity.Invoice; import com.myeshopping.invoiceservice.repository.InvoiceRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service @RequiredArgsConstructor public class InvoiceService { private final InvoiceRepository repository; @Transactional public Invoice generate(InvoiceRequest request){return repository.findByOrderId(request.getOrderId()).orElseGet(()->repository.save(Invoice.builder().invoiceNumber("INV-"+UUID.randomUUID().toString().substring(0,8).toUpperCase()).orderId(request.getOrderId()).paymentId(request.getPaymentId()).customerId(request.getCustomerId()).amount(request.getAmount()).currency(request.getCurrency().toUpperCase()).build()));} @Transactional(readOnly=true) public Invoice get(Long id){return repository.findById(id).orElseThrow(()->new IllegalArgumentException("Invoice not found: "+id));} @Transactional(readOnly=true) public Invoice getByOrder(Long orderId){return repository.findByOrderId(orderId).orElseThrow(()->new IllegalArgumentException("Invoice not found for order: "+orderId));} }
